WITH scored AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY order_id, status ORDER BY cost, id) event_seq, NTILE(4) OVER (PARTITION BY status ORDER BY cost, id) cost_bucket, MAX(cost) OVER (PARTITION BY order_id) order_id_max_cost FROM shipments) SELECT s.id, s.order_id, s.shipped_date, s.status, s.event_seq, s.cost_bucket, CASE WHEN status RLIKE '^(LOST|RETURNED)$' THEN 'GROUP_B' ELSE 'CORE' END AS status_zone, (SELECT MAX(p2.amount) FROM payments p2 WHERE p2.order_id = s.order_id) AS max_payment_amount FROM scored s
